-- Run this in Supabase SQL Editor for the NEW project.
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade);
create table if not exists public.inventory (id bigint generated by default as identity primary key, name text not null, category text not null, quantity integer not null default 0 check(quantity >= 0), condition text default 'Good', location text default '', responsible text default '', status text default 'Available', created_at timestamptz not null default now());
create table if not exists public.app_settings (id integer primary key check(id=1), categories text[] not null default array['Computer','Computer peripherals','Furniture','Electrical','Other']);
insert into public.app_settings(id) values(1) on conflict(id) do nothing;
create table if not exists public.activity (id bigint generated by default as identity primary key, action text not null, item text not null, actor text default 'User', created_at timestamptz not null default now());
alter table public.admin_users enable row level security;
alter table public.inventory enable row level security;
alter table public.app_settings enable row level security;
alter table public.activity enable row level security;
create or replace function public.is_schooltrack_admin() returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.admin_users where user_id=auth.uid()); $$;
grant execute on function public.is_schooltrack_admin() to authenticated;
-- Any signed-in guest can read. Only verified admin user can write.
drop policy if exists "signed in read inventory" on public.inventory;
create policy "signed in read inventory" on public.inventory for select to authenticated using(true);
drop policy if exists "admins manage inventory" on public.inventory;
create policy "admins manage inventory" on public.inventory for all to authenticated using(public.is_schooltrack_admin()) with check(public.is_schooltrack_admin());
drop policy if exists "signed in read settings" on public.app_settings;
create policy "signed in read settings" on public.app_settings for select to authenticated using(true);
drop policy if exists "admins manage settings" on public.app_settings;
create policy "admins manage settings" on public.app_settings for all to authenticated using(public.is_schooltrack_admin()) with check(public.is_schooltrack_admin());
drop policy if exists "signed in read activity" on public.activity;
create policy "signed in read activity" on public.activity for select to authenticated using(true);
drop policy if exists "admins add activity" on public.activity;
create policy "admins add activity" on public.activity for insert to authenticated with check(public.is_schooltrack_admin());
revoke all on public.admin_users from anon, authenticated;
